'{
  "$schema": "https://vega.github.io/schema/vega-lite/v5.json",
  "data": {
    "name": "dataset"
  },
  "width": 71.0,
  "height": 23.0,
  "autosize": {
    "type": "none"
  },
  "padding": 3,
  "transform": [
    {
      "filter": "datum[''Month''] != ''Unknown''"
    },
    {
      "calculate": "toNumber(slice(datum[''Month''], -4)) * 12 + indexof([''Jan'',''Feb'',''Mar'',''Apr'',''May'',''Jun'',''Jul'',''Aug'',''Sep'',''Oct'',''Nov'',''Dec''], slice(datum[''Month''], 0, 3))",
      "as": "mi"
    },
    {
      "joinaggregate": [
        {
          "op": "max",
          "field": "mi",
          "as": "last"
        }
      ]
    },
    {
      "filter": "datum.mi < datum.last"
    }
  ],
  "layer": [
    {
      "mark": {
        "type": "area",
        "interpolate": "monotone",
        "color": {
          "x1": 1,
          "y1": 1,
          "x2": 1,
          "y2": 0,
          "gradient": "linear",
          "stops": [
            {
              "offset": 0,
              "color": "rgba(235,104,52,0)"
            },
            {
              "offset": 1,
              "color": "rgba(235,104,52,0.35)"
            }
          ]
        }
      },
      "encoding": {
        "x": {
          "field": "mi",
          "type": "quantitative",
          "axis": null,
          "scale": {
            "zero": false,
            "nice": false
          }
        },
        "y": {
          "field": "No-show Rate",
          "type": "quantitative",
          "axis": null,
          "scale": {
            "zero": false
          }
        }
      }
    },
    {
      "mark": {
        "type": "line",
        "interpolate": "monotone",
        "color": "#EB6834",
        "strokeWidth": 1.8
      },
      "encoding": {
        "x": {
          "field": "mi",
          "type": "quantitative",
          "axis": null,
          "scale": {
            "zero": false,
            "nice": false
          }
        },
        "y": {
          "field": "No-show Rate",
          "type": "quantitative",
          "axis": null,
          "scale": {
            "zero": false
          }
        }
      }
    },
    {
      "transform": [
        {
          "window": [
            {
              "op": "rank",
              "as": "r"
            }
          ],
          "sort": [
            {
              "field": "mi",
              "order": "descending"
            }
          ]
        },
        {
          "filter": "datum.r == 1"
        }
      ],
      "mark": {
        "type": "circle",
        "size": 22,
        "color": "#EB6834",
        "opacity": 1
      },
      "encoding": {
        "x": {
          "field": "mi",
          "type": "quantitative",
          "axis": null,
          "scale": {
            "zero": false,
            "nice": false
          }
        },
        "y": {
          "field": "No-show Rate",
          "type": "quantitative",
          "axis": null,
          "scale": {
            "zero": false
          }
        }
      }
    }
  ]
}'

'{
  "background": null,
  "font": "Segoe UI",
  "view": {
    "stroke": null
  },
  "padding": 2,
  "axis": {
    "labelFont": "Segoe UI",
    "labelFontSize": 10,
    "labelColor": "#667085",
    "titleFont": "Segoe UI",
    "titleFontSize": 10,
    "titleColor": "#667085",
    "titleFontWeight": "normal",
    "domain": false,
    "ticks": false,
    "gridColor": "#EEF0F4",
    "labelPadding": 6
  },
  "legend": {
    "labelFont": "Segoe UI",
    "labelFontSize": 10.5,
    "labelColor": "#344054",
    "symbolType": "circle",
    "symbolSize": 70,
    "title": null,
    "orient": "top",
    "direction": "horizontal",
    "columnPadding": 14
  },
  "text": {
    "font": "Segoe UI",
    "fontSize": 11,
    "color": "#344054"
  },
  "title": {
    "font": "Segoe UI"
  },
  "concat": {
    "spacing": 8
  }
}'
